USE myenterprise;
SET NAMES utf8mb4;
START TRANSACTION;

-- -----------------------------------------------------------------------------
-- Core
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Catalog
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Warehouses and suppliers
-- -----------------------------------------------------------------------------
-- Inventory rows start at zero; the StockMovement ledger below fills them through trigger T1.

-- -----------------------------------------------------------------------------
-- Orders, payments and fulfillment
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Stock ledger (trigger T1 turns each row into an Inventory change)
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Returns and refunds (triggers T2 and T3 validate each row)
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Quality guarantee claims (trigger T5 validates each row)
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Shopping bags
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- Open reservations: units held for orders that have not shipped yet
-- -----------------------------------------------------------------------------
UPDATE Inventory i
  JOIN (SELECT oa.warehouse_id, oi.variant_id, SUM(oa.allocated_qty) AS qty
          FROM OrderAllocation oa
          JOIN OrderItem oi ON oi.order_item_id = oa.order_item_id
         WHERE oa.status = 'RESERVED'
         GROUP BY oa.warehouse_id, oi.variant_id) r
    ON r.warehouse_id = i.warehouse_id AND r.variant_id = i.variant_id
   SET i.quantity_reserved = r.qty;

COMMIT;
