INSERT INTO Product (product_id, admin_id, name, brand, description, isActive, slug, createdAt) VALUES
  (1, 3, 'Relaxed Linen Shirt', 'Field & Form', 'An airy button-up with a soft collar, dropped shoulders and a curved hem. Washed linen-cotton that gets softer every time it is worn.', 1, 'relaxed-linen-shirt', '2026-01-02 09:00:00'),
  (2, 3, 'Ribbed Cotton Tank', 'Common Thread', 'A fine rib tank with a scooped neck that layers under everything, from shirts to knitwear.', 1, 'ribbed-cotton-tank', '2026-01-02 09:00:00'),
  (3, 3, 'Everyday Cotton Tee', 'Common Thread', 'A clean crew neck in mid-weight organic jersey. Holds its shape wash after wash.', 1, 'everyday-cotton-tee', '2026-01-02 09:00:00'),
  (4, 3, 'Silk-Blend Shell Blouse', 'Willow Lane', 'A sleeveless shell with a fluid drape and a keyhole button at the back of the neck.', 1, 'silk-blend-shell-blouse', '2026-10-06 09:00:00'),
  (5, 3, 'Soft Knit Cardigan', 'Sunday Goods', 'A textured button-front knit for cool mornings, with horn-look buttons and ribbed cuffs.', 1, 'soft-knit-cardigan', '2026-01-02 09:00:00'),
  (6, 3, 'Merino Crew Sweater', 'Sunday Goods', 'Fine-gauge merino that is warm without bulk. Wears under a coat or on its own.', 1, 'merino-crew-sweater', '2026-01-02 09:00:00'),
  (7, 3, 'Chunky Rib Turtleneck', 'Sunday Goods', 'A deep rib turtleneck with a fold-over collar, knitted heavy for the first cold weeks.', 1, 'chunky-rib-turtleneck', '2026-10-10 09:00:00'),
  (8, 3, 'Gathered Midi Dress', 'Willow Lane', 'A softly gathered waist and a flowing skirt with deep side pockets.', 1, 'gathered-midi-dress', '2026-01-02 09:00:00'),
  (9, 3, 'Wrap Midi Dress', 'Willow Lane', 'An adjustable tie waist and a midi hem that moves when you walk.', 1, 'wrap-midi-dress', '2026-01-02 09:00:00'),
  (10, 3, 'Sleeveless Poplin Dress', 'Field & Form', 'Crisp poplin with an easy A-line skirt and side pockets. A summer piece, now archived.', 0, 'sleeveless-poplin-dress', '2026-01-02 09:00:00'),
  (11, 3, 'Satin Slip Skirt', 'Willow Lane', 'A bias-cut midi skirt with a narrow elastic waist. Dresses up a knit, dresses down with sneakers.', 1, 'satin-slip-skirt', '2026-01-02 09:00:00'),
  (12, 3, 'Pleated Wide-Leg Trousers', 'Field & Form', 'Fluid front pleats and a wide leg, cut high at the waist with a hook-and-bar fastening.', 1, 'pleated-wide-leg-trousers', '2026-01-02 09:00:00'),
  (13, 3, 'Straight-Leg Jeans', 'Common Thread', 'Classic five-pocket denim with a straight leg and a comfortable mid rise.', 1, 'straight-leg-jeans', '2026-01-02 09:00:00'),
  (14, 3, 'Linen Drawstring Trousers', 'Field & Form', 'Washed linen with an elastic drawstring waist and a relaxed, tapered leg.', 1, 'linen-drawstring-trousers', '2026-01-02 09:00:00'),
  (15, 3, 'Slim Stretch Chinos', 'Common Thread', 'Cotton twill with a little stretch, a slim leg and a clean, flat front.', 1, 'slim-stretch-chinos', '2026-01-02 09:00:00'),
  (16, 3, 'Selvedge Straight Jeans', 'Common Thread', 'Unwashed selvedge denim that fades to the way you wear it.', 1, 'selvedge-straight-jeans', '2026-01-02 09:00:00'),
  (17, 3, 'Everyday Trench Coat', 'Field & Form', 'A lightweight belted trench with storm flaps and a water-repellent finish.', 1, 'everyday-trench-coat', '2026-01-02 09:00:00'),
  (18, 3, 'Cropped Wool Blazer', 'Atelier Nine', 'A boxy single-breasted blazer cut short at the hip, with a fully lined body.', 1, 'cropped-wool-blazer', '2026-10-03 09:00:00'),
  (19, 3, 'Quilted Weekend Jacket', 'Sunday Goods', 'A light diamond-quilted layer with a cord collar and generous patch pockets.', 1, 'quilted-weekend-jacket', '2026-01-02 09:00:00'),
  (20, 3, 'Wool Overcoat', 'Atelier Nine', 'A knee-length single-breasted overcoat in dense, brushed wool.', 1, 'wool-overcoat', '2026-10-17 09:00:00'),
  (21, 3, 'Hooded Rain Jacket', 'Northbound', 'A packable waterproof shell with taped seams and an adjustable hood.', 1, 'hooded-rain-jacket', '2026-01-02 09:00:00'),
  (22, 3, 'Oxford Cotton Shirt', 'Field & Form', 'A button-down oxford with a soft roll to the collar. The shirt you reach for first.', 1, 'oxford-cotton-shirt', '2026-01-02 09:00:00'),
  (23, 3, 'Heavyweight Pocket Tee', 'Common Thread', 'Dense, boxy jersey with a chest pocket and a collar that stays flat.', 1, 'heavyweight-pocket-tee', '2026-01-02 09:00:00'),
  (24, 3, 'Everyday Court Sneakers', 'Stride Studio', 'Clean low-top court sneakers with a padded collar and a stitched rubber cupsole.', 1, 'everyday-court-sneakers', '2026-01-02 09:00:00'),
  (25, 3, 'Weekend Walking Sneakers', 'Stride Studio', 'Breathable mesh and a cushioned sole for long days on foot.', 1, 'weekend-walking-sneakers', '2026-01-02 09:00:00'),
  (26, 3, 'Suede Penny Loafers', 'Stride Studio', 'Easy slip-ons with a cushioned footbed and a classic penny strap.', 1, 'suede-penny-loafers', '2026-01-02 09:00:00'),
  (27, 3, 'Leather Chelsea Boots', 'Stride Studio', 'Pull-on Chelsea boots with a low stacked heel and a grippy lug sole.', 1, 'leather-chelsea-boots', '2026-01-02 09:00:00'),
  (28, 3, 'Leather Derby Shoes', 'Stride Studio', 'A Goodyear-welted derby that can be resoled, in polished leather.', 1, 'leather-derby-shoes', '2026-01-02 09:00:00'),
  (29, 3, 'Canvas Carryall Tote', 'Sunday Goods', 'A roomy canvas tote with an inner zip pocket for the small things.', 1, 'canvas-carryall-tote', '2026-01-02 09:00:00'),
  (30, 3, 'Everyday Crossbody Bag', 'Willow Lane', 'A compact zip-top bag with an adjustable strap, sized for a phone, keys and a card holder.', 1, 'everyday-crossbody-bag', '2026-01-02 09:00:00'),
  (31, 3, 'Weekender Duffle Bag', 'Northbound', 'A two-night duffle in waxed canvas with a shoe compartment and a padded strap.', 1, 'weekender-duffle-bag', '2026-01-02 09:00:00'),
  (32, 3, 'Ribbed Knit Scarf', 'Common Thread', 'A soft rib-knit scarf, long enough to wrap twice.', 1, 'ribbed-knit-scarf', '2026-01-02 09:00:00'),
  (33, 3, 'Leather Belt', 'Field & Form', 'A 3 cm full-grain belt with a solid brass buckle that ages with the leather.', 1, 'leather-belt', '2026-01-02 09:00:00'),
  (34, 3, 'Ribbed Wool Beanie', 'Common Thread', 'A close rib beanie in soft merino with a deep turn-up.', 1, 'ribbed-wool-beanie', '2026-10-01 09:00:00');
